<template>
  <div class="profile">
    <ProfileHeaderLocation
      :title="pageTitle"
      :backIcon="backIcon"
      :goBack="goBack"
    />

    <!-- Форма для создания города -->
    <div v-if="isCityPage" class="profile__wrapper">
      <AutosTextTemplate
        label="Город"
        :option="cityName"
        isSpecial
        @update:option="(value) => handleFieldUpdate('cityName', value)"
      />
      <CustomSelectSkeleton v-if="isRegionsLoading" />
      <div v-else class="form-group">
        <label class="form-group__label">Регион</label>
        <CustomSelectSearch v-model="selectedRegion" :options="regionOptions" />
      </div>
      <div class="form-checkbox">
        <CheckboxUI v-model="isRegionalCenter" />
        <span class="form-checkbox__note">Сделать региональным центром</span>
      </div>
      <AutosTextTemplate
        label="Предложный падеж"
        :option="cityPrepositional"
        @update:option="
          (value) => handleFieldUpdate('cityPrepositional', value)
        "
      />
      <AutosTextTemplate
        label="Транслит"
        :option="cityTransliteration"
        @update:option="
          (value) => handleFieldUpdate('cityTransliteration', value)
        "
      />
    </div>

    <!-- Форма для создания региона -->
    <div v-if="isRegionPage" class="profile__wrapper">
      <AutosTextTemplate
        label="Регион"
        :option="regionName"
        isSpecial
        @update:option="(value) => handleFieldUpdate('regionName', value)"
      />
      <AutosTextTemplate
        label="Предложный падеж"
        :option="regionPrepositional"
        @update:option="
          (value) => handleFieldUpdate('regionPrepositional', value)
        "
      />
      <AutosTextTemplate
        label="Транслит"
        :option="regionTransliteration"
        @update:option="
          (value) => handleFieldUpdate('regionTransliteration', value)
        "
      />
    </div>

    <div class="divider"></div>
    <div class="violation-form__actions">
      <ButtonUI
        :buttonClass="`btn--second`"
        :disabled="isSaveDisabled"
        @click="approvePublication"
        text="Сохранить"
      />
      <ButtonUI @click="rejectPublication" text="Отменить" />
    </div>
    <template v-if="showExitConfirm">
      <div class="modal-overlay">
        <div class="modal-window">
          <p class="modal-title">
            Вы уверены, что хотите покинуть страницу? Несохраненные данные будут
            потеряны.
          </p>
          <div class="modal-actions">
            <ButtonUI
              :buttonClass="`btn--second`"
              text="Всё равно покинуть"
              @click="confirmExit"
            />
            <ButtonUI text="Продолжить" @click="cancelExit" />
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';

import {
  getRegions,
  createNewCity,
  createNewRegion,
  getCityById,
  getRegionById,
  updateCity,
  updateRegion,
} from '@/services/apiClient';
import backIcon from '@/assets/icons/back-wide.svg';
import ProfileHeaderLocation from '@/components/UI/CustomProfileHeaderLocation.vue';
import AutosTextTemplate from '@/components/UI/AutosTextTemplate.vue';
import CustomSelectSearch from '@/components/UI/CustomSelectSearch.vue';
import CustomSelectSkeleton from '@/components/UI/CustomSelectSkeleton.vue';
import CheckboxUI from '@/components/UI/CheckboxUI.vue';
import ButtonUI from '@/components/UI/ButtonUI.vue';

const route = useRoute();
const router = useRouter();

const initialData = ref({});
const isChanged = computed(() => {
  if (isCityPage.value) {
    return (
      cityName.value !== initialData.value.cityName ||
      selectedRegion.value !== initialData.value.selectedRegion ||
      isRegionalCenter.value !== initialData.value.isRegionalCenter ||
      cityPrepositional.value !== initialData.value.cityPrepositional ||
      cityTransliteration.value !== initialData.value.cityTransliteration
    );
  }

  if (isRegionPage.value) {
    return (
      regionName.value !== initialData.value.regionName ||
      regionPrepositional.value !== initialData.value.regionPrepositional ||
      regionTransliteration.value !== initialData.value.regionTransliteration
    );
  }

  return false;
});

const handleFieldUpdate = (field, value) => {
  switch (field) {
    case 'cityName':
      cityName.value = value;
      break;
    case 'cityPrepositional':
      cityPrepositional.value = value;
      break;
    case 'cityTransliteration':
      cityTransliteration.value = value;
      break;
    case 'regionName':
      regionName.value = value;
      break;
    case 'regionPrepositional':
      regionPrepositional.value = value;
      break;
    case 'regionTransliteration':
      regionTransliteration.value = value;
      break;
    default:
      console.warn(`Неизвестное поле: ${field}`);
  }
};

// Определение типа страницы
const isCityPage = computed(() => route.params.type === 'city');
const isRegionPage = computed(() => route.params.type === 'region');
const mode = computed(() => (route.path.includes('/edit') ? 'edit' : 'create'));
const entityId = computed(() => route.params.id || null);

// Модели данных
const cityName = ref('');
const selectedRegion = ref(null);
const isRegionalCenter = ref(false);
const cityPrepositional = ref('');
const cityTransliteration = ref('');
const regionName = ref('');
const regionPrepositional = ref('');
const regionTransliteration = ref('');

const regionOptions = ref([]);
const isRegionsLoading = ref(false);

const isSaveDisabled = computed(() => {
  if (isCityPage.value) {
    return (
      !cityName.value ||
      !selectedRegion.value ||
      !cityPrepositional.value ||
      !cityTransliteration.value
    );
  }

  if (isRegionPage.value) {
    return (
      !regionName.value ||
      !regionPrepositional.value ||
      !regionTransliteration.value
    );
  }

  return true;
});

// Получаем регионы при монтировании компонента
const fetchRegions = async () => {
  isRegionsLoading.value = true;
  try {
    const response = await getRegions();
    regionOptions.value = response;
  } catch (error) {
    console.error('Ошибка при получении регионов:', error);
  } finally {
    setTimeout(() => {
      isRegionsLoading.value = false;
    }, 500);
  }
};

const fetchCityData = async (id) => {
  try {
    const res = await getCityById(id);
    cityName.value = res.title;
    cityPrepositional.value = res.prepositional_case;
    cityTransliteration.value = res.translit;
    selectedRegion.value = res.region.id;
    isRegionalCenter.value = !!res.is_regional_center;

    initialData.value = {
      cityName: res.title,
      cityPrepositional: res.prepositional_case,
      cityTransliteration: res.translit,
      selectedRegion: res.region.id,
      isRegionalCenter: !!res.is_regional_center,
    };
  } catch (e) {
    console.error('Ошибка при загрузке города', e);
  }
};

const fetchRegionData = async (id) => {
  try {
    const res = await getRegionById(id);
    regionName.value = res.title;
    regionPrepositional.value = res.prepositional_case;
    regionTransliteration.value = res.translit;

    initialData.value = {
      regionName: res.title,
      regionPrepositional: res.prepositional_case,
      regionTransliteration: res.translit,
    };
  } catch (e) {
    console.error('Ошибка при загрузке региона', e);
  }
};

onMounted(() => {
  if (isCityPage.value) {
    fetchRegions();
    // нужен ли этот лог в проекте
    console.log('route.params:', route.params);
    if (mode.value === 'edit' && entityId.value) {
      fetchCityData(entityId.value);
    }
  } else if (isRegionPage.value && mode.value === 'edit' && entityId.value) {
    fetchRegionData(entityId.value);
  }
});

const pageTitle = computed(() => {
  if (mode.value === 'create') {
    if (isCityPage.value) return 'Заявка на создание города';
    if (isRegionPage.value) return 'Заявка на создание региона';
  } else if (mode.value === 'edit') {
    if (isCityPage.value) return 'Редактирование города';
    if (isRegionPage.value) return 'Редактирование региона';
  }
  return 'Заявка';
});

const goBack = () => {
  router.back();
};

const approvePublication = async () => {
  if (mode.value === 'create') {
    await handleCreate();
  } else if (mode.value === 'edit') {
    await handleEdit();
  }
};

const handleCreate = async () => {
  if (isCityPage.value) {
    const payload = {
      title: cityName.value,
      region_id: selectedRegion.value,
      is_regional_center: isRegionalCenter.value ? 1 : 0,
      prepositional_case: cityPrepositional.value,
      translit: cityTransliteration.value,
      is_cnc: 0,
    };

    const res = await createNewCity(payload);
    if (res.success !== false) {
      router.back();
    }
  } else if (isRegionPage.value) {
    const payload = {
      title: regionName.value,
      prepositional_case: regionPrepositional.value,
      translit: regionTransliteration.value,
    };

    const res = await createNewRegion(payload);
    if (res.success !== false) {
      router.back();
    }
  }
};

const handleEdit = async () => {
  if (!entityId.value) return;

  if (isCityPage.value) {
    const payload = {
      id: entityId.value,
      title: cityName.value,
      region_id: selectedRegion.value,
      is_regional_center: isRegionalCenter.value ? 1 : 0,
      prepositional_case: cityPrepositional.value,
      translit: cityTransliteration.value,
      is_cnc: 0,
    };

    const res = await updateCity(entityId.value, payload);
    if (res.success !== false) {
      router.back();
    }
  } else if (isRegionPage.value) {
    const payload = {
      id: entityId.value,
      title: regionName.value,
      prepositional_case: regionPrepositional.value,
      translit: regionTransliteration.value,
    };

    const res = await updateRegion(entityId.value, payload);
    if (res.success !== false) {
      router.back();
    }
  }
};

const showExitConfirm = ref(false);

const rejectPublication = () => {
  if (isChanged.value) {
    showExitConfirm.value = true;
  } else {
    router.back();
  }
};

const confirmExit = () => {
  showExitConfirm.value = false;
  router.back();
};

const cancelExit = () => {
  showExitConfirm.value = false;
};
</script>

